48	/// Scriptable fakes (not mocktail — same convention
49	/// `insertion_modal_audio_test.dart`'s own fakes already use) standing in
50	/// for spec-3-3's two new ports. Never exercises the real `image_picker`
51	/// plugin (Never, AGENTS.md: no device/simulator exists).
52	class _FakePhotoPicker implements PhotoPicker {
53	  PickedPhoto? nextCameraResult;
54	  PickedPhoto? nextGalleryResult;
55	  int cameraCalls = 0;
56	  int galleryCalls = 0;
57	
58	  /// Lets a test hold `pickFromCamera()` unresolved, to simulate leaving
59	  /// the Foto tab while the native picker dialog is theoretically still
60	  /// open (I/O matrix: "Leave tab mid-pick/OCR" — the "mid-pick" half).
61	  /// Deliberately on the *picker* call, not `MediaRepository.
62	  /// recognizeText()` — gating that one would require the real file
63	  /// read (`PhotoEntryCubit._recognize()`) to have already run inside
64	  /// `tester.runAsync()`, which cannot be pumped concurrently with
65	  /// (`WidgetTester.pump`/`runAsync` cannot interleave — confirmed by
66	  /// direct probe); this `Completer` is plain Dart, so it works
67	  /// regardless of zone.
68	  Completer<void>? cameraGate;
69	
70	  @override
71	  Future<PickedPhoto?> pickFromCamera() async {
72	    cameraCalls++;
73	    final activeGate = cameraGate;
74	    if (activeGate != null) {
75	      await activeGate.future;
76	    }
77	    return nextCameraResult;
78	  }
79	
80	  @override
81	  Future<PickedPhoto?> pickFromGallery() async {
82	    galleryCalls++;
83	    return nextGalleryResult;
84	  }
85	}
