155	/// Coarse `AudioCaptureState` discriminator used only to decide whether a
156	/// given emission is a genuine transition worth announcing — e.g.
157	/// [AudioRecording]'s own per-second timer tick re-emits the same kind
158	/// repeatedly and must never re-announce "Gravando áudio" every second.
159	enum _AudioAnnounceKind {
160	  idle,
161	  recording,
162	  processing,
163	  transcribed,
164	  saving,
165	  saved,
166	  error,
167	}
168	
169	_AudioAnnounceKind _audioAnnounceKindOf(AudioCaptureState state) =>
170	    switch (state) {
171	      AudioIdle() => _AudioAnnounceKind.idle,
172	      AudioRecording() => _AudioAnnounceKind.recording,
173	      AudioProcessing() => _AudioAnnounceKind.processing,
174	      AudioTranscribed(saving: true) => _AudioAnnounceKind.saving,
175	      AudioTranscribed() => _AudioAnnounceKind.transcribed,
176	      AudioSaved() => _AudioAnnounceKind.saved,
177	      AudioError() => _AudioAnnounceKind.error,
178	    };
179	
180	/// Same "only announce a genuine transition" role as [_AudioAnnounceKind],
181	/// for `PhotoEntryCubit`.
182	enum _PhotoAnnounceKind { idle, processing, recognized, saving, saved, error }
183	
184	_PhotoAnnounceKind _photoAnnounceKindOf(PhotoCaptureState state) =>
185	    switch (state) {
186	      PhotoIdle() => _PhotoAnnounceKind.idle,
187	      PhotoProcessing() => _PhotoAnnounceKind.processing,
188	      PhotoRecognized(saving: true) => _PhotoAnnounceKind.saving,
189	      PhotoRecognized() => _PhotoAnnounceKind.recognized,
190	      PhotoSaved() => _PhotoAnnounceKind.saved,
191	      PhotoError() => _PhotoAnnounceKind.error,
192	    };
